  "upgrade.providerConfirmNote": "Le modifiche al piano richiedono la conferma del fornitore di fatturazione. Qualsiasi differenza di prezzo, conguaglio e data di decorrenza devono essere mostrati prima che tu approvi la modifica. Un passaggio a un piano superiore non deve creare un secondo abbonamento simultaneo.",
