  "exports.eyebrow": "Dati",
  "exports.title": "Esportazioni e backup",
  "exports.subtitleStart": "I download sono sempre limitati a",
  "exports.subtitleRest": ". Ogni file è etichettato con il nome dell'attività e la data di creazione.",
  "exports.createBusinessFirst": "Crea prima un'attività: le esportazioni appartengono a un'attività, non all'app.",
  "exports.lockedTitle": "Le esportazioni CSV ed Excel sono una funzionalità Business",
  "exports.lockedDesc": "Il tuo spazio di lavoro è sul piano Essentials. Business aggiunge esportazioni CSV ed Excel, valutazione delle scorte, prodotti e personale illimitati, fornitori, acquisti e pacchetti.",
  "exports.seeBusiness": "Vedi cosa include Business",
  "exports.whatTheseAre": "Cosa sono questi file",
  "exports.about1": "Ogni set di dati è disponibile come CSV o come vera cartella di lavoro Excel (.xlsx): la cartella completa dell'inventario è solo Excel, con un foglio per set di dati. I file CSV si aprono in Excel, Numbers, Google Sheets e nella maggior parte delle app di magazzino. Testo UTF-8, virgole tra virgolette, interruzioni di riga nelle note e zeri iniziali nei codici sono tutti conservati, e le celle che iniziano come una formula vengono neutralizzate in modo che un foglio di calcolo le apra come testo.",
  "exports.about2": "Nei file Excel, SKU, UPC, ISBN e codici a barre sono celle di testo: mai notazione scientifica e mai zeri tagliati, con larghezze di colonna, filtri di intestazione e formati di valuta o quantità applicati. La cartella completa dell'inventario tiene prodotti, livelli di scorte, sedi e movimenti su fogli separati.",
  "exports.about3": "Le esportazioni molto grandi si fermano a 20.000 righe per set di dati: quando succede, il nome del file lo dice (truncated-20000), così un file parziale non passa mai per completo.",
  "exports.about4": "Un backup è un'istantanea dei tuoi dati, non un ripristino in un clic. Ripristinarlo è un lavoro manuale, prima con revisione, quindi conserva il file al sicuro: nulla nell'app può ancora ricreare da esso un'attività eliminata. Il codice dell'app e i backup della piattaforma Base44 sono gestiti separatamente da questi file.",
  "exports.about5": "Foto e allegati sono elencati come i loro link memorizzati: i file immagine stessi non sono inclusi nel download.",
  "exports.backupTitle": "Backup completo",
  "exports.backupDesc": "Un file con prodotti, sedi, livelli di scorte, registro completo dei movimenti, fornitori, acquisti, ordini, resi, conteggi e inserzioni di questa attività, oltre alle impostazioni del profilo. Conservalo in un luogo che controlli.",
  "exports.backupIncludes1": "Prodotti, codici, costi e note",
  "exports.backupIncludes2": "Sedi e quantità per sede",
  "exports.backupIncludes3": "Ogni movimento, con autore e ora",
  "exports.backupIncludes4": "Acquisti, ordini, resi e conteggi",
  "exports.buildingBackup": "Creazione del backup in corso…",
