  "print.chooseStyleHint": "Scegli uno stile, poi scegli i prodotti dall'elenco. L'anteprima mostra esattamente ciò che esce dalla stampante.",
  "print.howToReach": "Come raggiungere la stampante",
  "print.howIntro": "Questa app si collega alle stampanti che possiedi già: non è una stampante di per sé. Ci sono quattro modi per raggiungerne una, e le etichette si stampano su entrambi i piani con qualsiasi modo. Bolle di accompagnamento, ordini d'acquisto, documenti dei fornitori e report sono riservati a Business, qualunque sia la connessione.",
  "print.howBluetoothLead": "Bluetooth.",
  "print.howBluetoothBody": "Da questa pagina, su Chrome o Edge desktop e su Chrome Android: scegli la tua stampante di etichette e le etichette vanno direttamente a essa. Non funziona in Safari su iOS: su iPhone, la stampa Bluetooth arriva invece con l'app mobile. Una stampante che parla solo Zebra ZPL o il linguaggio proprio di Brother non capirà le etichette inviate da questa pagina; questo viene verificato su stampanti reali prima di dichiararlo funzionante.",
  "print.howWifiLead": "Wi-Fi.",
  "print.howWifiBody": "Installa la stampante sul Wi-Fi del tuo negozio, poi usa il pulsante Stampa: stampa tramite la stampante installata su questo computer, attraverso la rete del negozio. Su iPhone, AirPrint è integrato: una stampante AirPrint sullo stesso Wi-Fi appare semplicemente nel foglio di stampa, senza cavo e senza app, e l'app non ha bisogno di codice specifico per AirPrint. La stampante deve supportare AirPrint (la maggior parte delle nuove lo fa) e telefono e stampante devono essere sullo stesso Wi-Fi.",
  "print.howEthernetLead": "Ethernet.",
  "print.howEthernetBody": "Collega la stampante alla rete del negozio con un cavo Ethernet, installala sul computer e stampa tramite il pulsante Stampa. Ethernet è un percorso per desktop e computer: gli iPhone non usano cavi Ethernet.",
  "print.howUsbLead": "USB.",
  "print.howUsbBody": "Collega la stampante al computer con il suo cavo e usa il pulsante Stampa: stampa tramite la stampante installata lì. Su un telefono Android con cavo USB OTG, il pulsante USB qui sopra parla direttamente con la stampante. Gli iPhone non possono stampare direttamente via USB — niente WebUSB lì — quindi usa Wi-Fi / AirPrint oppure il Bluetooth dall'app mobile.",
  "print.howCordsLead": "I cavi servono ancora agli iPhone, di un passo.",
  "print.howCordsBody": "Una stampante USB collegata al computer del negozio, o una stampante Ethernet cablata alla rete, appare sul tuo iPhone tramite il Wi-Fi del negozio (AirPrint / stampante condivisa): i cavi mettono la stampante in rete in modo solido e il telefono la raggiunge senza fili.",
  "print.howOfflineLead": "Se internet cade,",
  "print.howOfflineBody": "le etichette e i documenti già su questa pagina si stampano comunque: il pulsante Stampa, il PDF delle etichette, Bluetooth e USB non hanno bisogno di connessione. Ciò che ha bisogno di internet è caricare la pagina e i suoi prodotti in primo luogo. La modalità offline completa (lavorare nell'app senza alcuna connessione) è una build separata e più grande e non viene dichiarata qui.",
