  "settings.cancelTerms.intro": "Queste sono le condizioni per gli abbonamenti a pagamento di Luminous StockHaven. La fatturazione degli abbonamenti del sito web avviene tramite Stripe. Puoi annullare il tuo abbonamento da solo in qualsiasi momento usando il pulsante Annulla l'abbonamento qui sotto: non serve l'approvazione del personale. Le richieste di cancellazione e rimborso possono essere gestite anche tramite il contatto ufficiale di assistenza clienti, theluminousbookshop@outlook.com.",
  "settings.cancelTerms.noApprovalBody": "Puoi annullare il tuo abbonamento da solo in qualsiasi momento. Non è richiesta l'approvazione del personale. I rinnovi futuri si interrompono solo dopo che il fornitore di fatturazione conferma la cancellazione.",
  "settings.cancelTerms.noApprovalTitle": "Annulla senza approvazione:",
  "settings.cancelTerms.paymentBody": "Per le prove a pagamento, la prova di sette giorni richiede un metodo di pagamento all'iscrizione. Se non viene annullata entro la scadenza di cancellazione della prova applicabile, il piano mensile selezionato verrà addebitato automaticamente dopo la prova. Il prezzo, la prima data di fatturazione e la scadenza di cancellazione specifica del fornitore devono essere mostrati durante l'iscrizione. La fatturazione della prova avviene tramite Stripe.",
  "settings.cancelTerms.paymentTitle": "Metodo di pagamento e rinnovo automatico:",
  "settings.cancelTerms.remainingBody": "Se hai già pagato un periodo di fatturazione, puoi mantenere l'accesso fino a quella data di pagamento verificata. Una cessazione anticipata richiede un'adeguata conferma del fornitore e l'eventuale gestione del rimborso. L'accesso alla prova gratuita termina secondo la data di fine prova confermata dal fornitore.",
  "settings.cancelTerms.remainingTitle": "Accesso rimanente:",
  "settings.cancelTerms.storesBody": "Se mai ti abboni tramite Google Play o l'Apple App Store, il tuo abbonamento viene fatturato e gestito da quello store. Potrebbe essere necessario annullarlo direttamente nella sezione abbonamenti dello stesso account Google o Apple usato per abbonarti. Annullare un abbonamento separato del sito web, disinstallare questa app o richiedere l'eliminazione dell'account Luminous StockHaven non annulla automaticamente un abbonamento fatturato dallo store. Controlla la ricevuta d'acquisto per confermare chi ti fattura.",
  "settings.cancelTerms.storesTitle": "Abbonamenti Google Play e Apple App Store (se mai ti abboni tramite uno store):",
  "settings.cancelTerms.title": "Termini e condizioni di cancellazione",
  "settings.cancelTerms.trialBody": "La prova di sette giorni può essere usata una sola volta per cliente idoneo. Annullare una prova o un abbonamento non concede un'altra prova; i clienti che ritornano devono scegliere un abbonamento a pagamento.",
  "settings.cancelTerms.trialTitle": "Una sola prova gratuita:",
  "settings.canceled.endsOn": "Questo abbonamento è annullato e termina il {date}. Mantieni l'accesso completo fino ad allora.",
  "settings.delete.checking": "Controllo di una richiesta di eliminazione esistente in corso…",
  "settings.delete.description": "Richiedi la rimozione del tuo account di accesso Luminous StockHaven.",
  "settings.delete.dialogDescription": "Questo richiede una revisione dell'eliminazione dell'account. Non rimuove immediatamente il tuo accesso o l'inventario e non annulla alcun abbonamento Stripe. Digita {word} per confermare che vuoi inviare la richiesta.",
  "settings.delete.dialogTitle": "Richiedi l'eliminazione dell'account",
  "settings.delete.enterDelete": "Digita {word} per confermare",
  "settings.delete.exportFirst": "Esporta prima il tuo inventario se devi conservare i tuoi record.",
  "settings.delete.intro": "Inviare una richiesta non elimina immediatamente il tuo account, le attività o l'inventario. Le richieste vengono esaminate separatamente prima che l'eliminazione possa essere completata. Questa richiesta non annulla un abbonamento Stripe né interrompe la fatturazione futura; la cancellazione dell'abbonamento deve essere gestita separatamente tramite il fornitore di fatturazione.",
  "settings.delete.keepAccount": "Mantieni l'account",
  "settings.delete.noExport": "Essentials non ha esportazione: annota tutto ciò di cui hai bisogno prima di richiedere l'eliminazione.",
  "settings.delete.notDeleted": "Il tuo account e i tuoi dati non sono stati eliminati da questa richiesta. La fatturazione non è stata annullata.",
