  "settings.trial.cancelKeeps": "Annullare durante la prova mantiene i tuoi 7 giorni completi: l'accesso termina il {date} e non ti verrà addebitato nulla.",
  "staff.access.noSeatBody": "Il tuo account non ha un posto nel personale per questa attività, quindi le sue scorte restano chiuse. Chiedi al proprietario di aggiungerti in Personale e ruoli.",
  "staff.access.noSeatTitle": "Questa attività non è aperta al tuo accesso",
  "staff.access.pendingBody": "Questa attività ha un invito per la tua email che non è stato attivato. Chiedi al proprietario di impostare il tuo stato di personale su attivo. Fino ad allora nulla qui è visibile.",
  "staff.access.pendingTitle": "Il tuo invito non è ancora attivo",
  "staff.access.signOut": "Esci",
  "staff.access.suspendedBody": "Un amministratore ha sospeso questo account del personale per l'attività attiva. Chiedigli di riportarti ad attivo, poi accedi di nuovo.",
  "staff.access.suspendedTitle": "Il tuo accesso è in pausa",
  "staff.addFirst": "Aggiungi il primo membro del personale",
  "staff.addMember": "Aggiungi membro del personale",
  "staff.emptyBody": "Aggiungi una persona, assegnale un ruolo e i permessi che ne derivano, e verrà invitata via email ad accedere a questa attività.",
  "staff.emptyTitle": "Ancora nessun personale",
  "staff.eyebrow": "Squadra",
  "staff.how.p1": "Ogni membro ha un ruolo e il proprio elenco di permessi, quindi puoi partire da un ruolo e cambiare una cosa senza creare un nuovo ruolo. Modificare un ruolo non riscrive i membri che già lo hanno: apri un membro per riapplicare i valori predefiniti del suo ruolo.",
  "staff.how.p2": "I ruoli personalizzati sono una funzionalità Business: Essentials usa i cinque ruoli integrati (Proprietario, Responsabile, Addetto al magazzino, Addetto alle vendite, Visualizzatore).",
  "staff.how.p3": "Gli inviti vengono inviati via email. Un membro può accedere solo dopo aver accettato, e rimuovere qualcuno da questo elenco non elimina il suo account nell'app.",
  "staff.how.p4": "Un negozio è la sede a cui una persona è assegnata. Viene registrata sulla sua scheda; ciò che può aprire è comunque deciso dal suo ruolo e dai suoi permessi.",
  "staff.how.p5": "I permessi decidono cosa può aprire ogni persona: le voci di menu fuori dal suo ruolo sono nascoste, e un indirizzo bloccato mostra un avviso «non nel tuo ruolo» invece della pagina. Una modifica si applica la prossima volta che quella persona carica l'app; sospendere un membro lo esclude completamente.",
  "staff.how.p6": "Gli amministratori possono vedere e modificare tutti i dati, gestire utenti e ruoli dell'app, e non sono mai limitati da un ruolo del personale. Chi non ha un record di personale — il proprietario di una nuova attività — mantiene l'accesso completo.",
  "staff.howTitle": "Come funzionano personale e ruoli",
  "staff.limitBadgeLabel": "Personale",
  "staff.loading": "Caricamento del personale in corso…",
