  "payroll.dd.savings": "Conto di risparmio",
  "payroll.dd.steps.body": "1. Ti serve un conto bancario aziendale in grado di inviare pagamenti ACH. 2. Raccogli un modulo di autorizzazione firmato da ogni membro del team — un assegno annullato aiuta a verificare i numeri. 3. Invia le buste paga 2-3 giorni lavorativi prima del giorno di paga, così i soldi arrivano in tempo. 4. La maggior parte degli stati richiede il consenso scritto del membro del team. Questa app raccoglie i moduli e ti guida passo passo — l'invio vero e proprio del denaro avviene tramite la tua banca.",
