  "training.warningSentOn": "Avviso inviato il {date}",
  "auth.sameEmailNotice": "Hai già la nostra app da Google Play o dall'App Store? Usa qui la stessa email — quella con cui accedi all'app — così il tuo negozio e il tuo inventario vengono con te. Un'email diversa crea un negozio completamente nuovo e vuoto.",
