  "recovery.emailMeCodeHint": "Se hai impostato un'email di backup, invieremo lì un codice di 6 cifre. Per proteggere il tuo account, questa pagina risponde sempre allo stesso modo — che un codice sia stato inviato o no.",
  "recovery.codeSent": "Se la tua email di backup è registrata, un codice di 6 cifre è in arrivo lì ora. Scade tra 10 minuti.",
