  "recovery.changeIntro": "Sei dentro — solo per un passaggio: scegli la nuova email per il tuo account. Il tuo negozio, il tuo inventario e l'accesso del tuo team si spostano con essa.",
  "recovery.doneBody": "L'email del tuo account è cambiata e questo accesso è di nuovo il tuo normale accesso. Bentornato.",
