  "settings.security.title": "Sicurezza e chiavi di riserva",
  "settings.security.description": "Prepara le tue chiavi di riserva PRIMA di averne bisogno: se perdi mai l'accesso all'email del tuo account, sono il modo per riavere il tuo negozio.",
  "settings.security.genericError": "Qualcosa è andato storto. Riprova.",
  "settings.security.accountEmail": "Email dell'account",
  "settings.security.backupCodesTitle": "Codici di backup",
  "settings.security.backupCodesDesc": "Chiavi di riserva monouso. Stampale o scrivile e conservale in un posto sicuro — ognuna può riportarti dentro una volta se perdi la tua email.",
  "settings.security.codesRemaining": "Codici di backup inutilizzati rimasti: {count}",
  "settings.security.generateCodes": "Genera codici di backup",
