  "settings.security.newCodesTitle": "I tuoi nuovi codici di backup",
  "settings.security.codesOnceWarning": "Questi codici vengono mostrati una volta sola — ne conserviamo solo una copia cifrata, quindi nemmeno noi possiamo mostrarteli di nuovo. Generare un nuovo set annulla ogni codice precedente.",
  "settings.security.printCodes": "Stampa questi codici",
  "settings.security.backupEmailTitle": "Email di backup",
  "settings.security.backupEmailDesc": "Un secondo indirizzo email che controlli tu. Se la tua email principale è mai irraggiungibile, un codice di recupero può essere inviato qui invece.",
  "settings.security.backupEmailLabel": "Indirizzo email di backup",
