  "settings.security.backupEmailPending": "Abbiamo inviato un codice di 6 cifre a quell'indirizzo. Inseriscilo qui per finire di impostarla come tua email di backup.",
  "settings.security.backupEmailVerified": "Email di backup verificata: {email}",
  "settings.security.backupEmailNone": "Nessuna email di backup impostata finora.",
  "settings.security.verifyCodeLabel": "Codice di 6 cifre",
