  "rewards.subtitle": "Di' grazie con un premio — una percentuale di sconto, una carta regalo o qualsiasi cosa tu descriva.",
  "rewards.title": "Premi e incentivi",
  "rewards.value.giftCard": "Carta regalo da {value}",
  "rewards.value.percentOff": "{percent}% di sconto in negozio",
  "rewards.void": "Annulla",
  "rewards.voided": "Premio annullato.",
  "workforce.tab.rewards": "Premi",
  "training.lessons.mgr-give-rewards.step1": "Apri Team e tocca Premi. Scegli il membro del team, poi il tipo: una percentuale di sconto in negozio, una carta regalo o qualcos'altro che descrivi con parole tue.",
  "training.lessons.mgr-give-rewards.step2": "Dai al premio un nome breve e una nota se vuoi. La persona riceve subito una campanella, e il premio la aspetta nei suoi I miei premi con il suo codice.",
  "training.lessons.mgr-give-rewards.step3": "Il limite, per progettazione: premi SOLO il PERSONALE. Non puoi premiare te stesso o un altro responsabile — premiare un responsabile è una decisione del titolare, e l'app lo rifiuterà chiaramente.",
  "training.lessons.mgr-give-rewards.step4": "Alla cassa, digita il codice che ti mostra il membro del team e segnalo come utilizzato — ogni codice funziona una volta. Puoi annullare un premio che hai assegnato se i piani cambiano; i doni del titolare spetta al titolare annullarli.",
  "training.lessons.mgr-give-rewards.title": "Assegnare premi al tuo personale",
  "training.lessons.owner-give-rewards.step1": "I premi vivono in Team, nella scheda Premi, e sono solo per il piano Business — con Essentials la scheda mostra una porta chiusa, così il tuo team può vedere cosa offre il piano più grande.",
  "training.lessons.owner-give-rewards.step2": "Puoi premiare CHIUNQUE nel team — personale e responsabili allo stesso modo. Scegli la persona, poi il tipo: una percentuale di sconto in negozio (qualsiasi percentuale tu scelga), una carta regalo per qualsiasi luogo, o qualsiasi incentivo tu descriva con parole tue.",
  "training.lessons.owner-give-rewards.step3": "Il premio arriva con il suo codice monouso e fa suonare la campanella della persona. Mostra il codice alla cassa; un titolare o un responsabile lo digita per segnarlo come utilizzato.",
  "training.lessons.owner-give-rewards.step4": "Una ricevuta del premio stampata o condivisa riporta solo il nome della TUA attività — mai quello dell'app. È il grazie del tuo negozio, non una pubblicità.",
  "training.lessons.owner-give-rewards.title": "Assegnare premi (piano Business)",
  "training.lessons.owner-rewards-oversight.step1": "Anche il tuo responsabile può assegnare premi — solo al personale. L'app rifiuta un responsabile che premia se stesso o un altro responsabile; premiare un responsabile è sempre una tua decisione.",
  "training.lessons.owner-rewards-oversight.step2": "Vedi ogni premio dell'attività nella Cronologia dei premi: chi l'ha assegnato, chi l'ha ricevuto e se è pronto, utilizzato o annullato. Un responsabile vede solo i premi che ha assegnato e quelli che ha ricevuto.",
  "training.lessons.owner-rewards-oversight.step3": "Puoi annullare qualsiasi premio, compreso uno assegnato dal tuo responsabile. Un responsabile può annullare i propri doni, ma mai i tuoi.",
  "training.lessons.owner-rewards-oversight.step4": "Ogni codice funziona esattamente una volta, e un premio annullato non può mai essere usato — la cronologia mostra sempre come è finito un premio.",
  "training.lessons.owner-rewards-oversight.title": "Supervisionare i premi: le assegnazioni del tuo responsabile",
  "training.lessons.staff-your-rewards.step1": "Quando il tuo responsabile o il titolare ti assegna un premio, la tua campanella suona. Apri Team e tocca Premi per vederlo sotto I miei premi.",
  "training.lessons.staff-your-rewards.step2": "Ogni premio ha il suo codice. Tienilo per te — chi mostra il codice alla cassa è chi usa il premio.",
  "training.lessons.staff-your-rewards.step3": "Per usarlo, mostra il codice quando compri. La persona alla cassa lo digita e lo segna come utilizzato — ogni codice funziona esattamente una volta.",
  "training.lessons.staff-your-rewards.step4": "I premi sono un piacere del piano Business. Se il tuo negozio non è su Business, la scheda Premi mostra invece una porta chiusa — è il piano, non un errore.",
  "training.lessons.staff-your-rewards.title": "I tuoi premi: trovare il tuo codice e usarlo",
  "training.module.rewards": "Premi e incentivi",
