  "pos.events.heldPlanNote": "Alcune vendite qui sotto sono arrivate mentre questo negozio non era sul piano Business. Sono state conservate al sicuro e nulla è stato conteggiato. Ora che il negozio è su Business, puoi conteggiarle.",
